css:
.dcx *{ box-sizing: border-box; }
.dcx{ margin: 0; background: #F5F7F3; }
.dcx a[style*="inline-flex"]{ white-space: nowrap; }
.dcx img{ max-width: 100%; }
@media (prefers-reduced-motion: reduce){.dcx *,.dcx *::before,.dcx *::after{ animation-duration: .01ms !important; animation-iteration-count: 1 !important; transition-duration: .01ms !important; scroll-behavior: auto !important; }
}
.dcx a{ color: #0B6B3F; text-decoration: none; }
.dcx a:hover{ color: #16A85F; }
.dcx :focus-visible{ outline: 2px solid #16A85F; outline-offset: 3px; }
@media (max-width: 720px){.dcx [data-pad]{ padding-left: 18px !important; padding-right: 18px !important; }
.dcx [data-h1]{ font-size: 32px !important; }
.dcx [data-h2]{ font-size: 24px !important; }
}
@media (max-width: 1180px){.dcx [data-adhero]{ grid-template-columns: minmax(0,1fr) !important; }
.dcx [data-wall]{ max-width: 620px; margin: 0 auto; }
.dcx [data-builder]{ grid-template-columns: minmax(0,1fr) !important; }
.dcx [data-stepper]{ flex-direction: row !important; flex-wrap: wrap; }
.dcx [data-stepper] > li{ flex: 1 1 200px !important; }
.dcx [data-funnel]{ grid-template-columns: minmax(0,1fr) !important; }
.dcx [data-ab]{ grid-template-columns: minmax(0,1fr) !important; }
}
@media (max-width: 720px){.dcx [data-wall]{ grid-template-columns: repeat(2, minmax(0,1fr)) !important; }
.dcx [data-wall] > *{ transform: none !important; margin: 0 !important; }
.dcx [data-abpair]{ grid-template-columns: minmax(0,1fr) !important; }
.dcx [data-rules]{ grid-template-columns: minmax(0,1fr) !important; }
}
.dch-62613db1:hover{background: #C5F0D8 !important;color: #0B3B2A !important}
.dch-4371d45f:hover{background: rgba(255,255,255,.1) !important;color: #fff !important}
